    // (the ready-made questions say so too: a keyboard press on one while a reply is pending does nothing)
    new MutationObserver(() => { const busy = !!box.querySelector('.typing'); win.toggleAttribute('data-busy', busy); chips.querySelectorAll('button').forEach(b => busy ? b.setAttribute('aria-disabled', 'true') : b.removeAttribute('aria-disabled')); }).observe(box, {childList:true});
