      list.forEach(s => { const n = nums(price(s)); lo += n[0] || 0; hi += n[1] || n[0] || 0; if (n.length >= 4) { mlo += n[2]; mhi += n[3]; } if (days(s.time) > days(longest.time)) longest = s; });
