// Shared motion. LEAD ONLY. Never for reduced motion or automated browsers (?rv=1 lifts that guard).
// The rule of the site: what the visitor sees when a page opens is there at once (the home hero has its own short entrance in home.css);
// further down, whole sections arrive quietly as they are reached, never small items one by one. Numbers count up once.
// The hidden state exists only while html.rv is set, so the page reads whole without script, with reduced motion, and if the observer never reports.
(function(){
  const {reduce} = ZX;
  const auto = navigator.webdriver && !/[?&]rv=1/.test(location.search);
  if (reduce || auto || !window.IntersectionObserver) return;
  const h = document.documentElement;
  const SEL = '.band .head, [data-rv], .tcards, .faq, .pains, .trytxt';
  const countUp = n => {
    const to = +n.getAttribute('data-count'), t0 = performance.now();
    const tick = now => { const k = Math.min(1, (now - t0) / 1100); n.textContent = k < 1 ? Math.round(to * (1 - Math.pow(1 - k, 3))) : to; if (k < 1) requestAnimationFrame(tick); };
    requestAnimationFrame(tick);
  };
  let heard = false;
  const io = new IntersectionObserver(es => {
    heard = true;
    es.forEach(e => {
      if (!e.isIntersecting) return;
      io.unobserve(e.target); e.target.classList.add('in-view');
      e.target.querySelectorAll('[data-count]').forEach(countUp);
    });
  }, {rootMargin:'0px 0px -7% 0px'});
  // only blocks that start below the visible part of the page wait; one block per section (a block inside another block does not wait twice)
  const fold = innerHeight;
  const all = [...document.querySelectorAll(SEL)];
  const blocks = all.filter(n => n.getBoundingClientRect().top >= fold && !all.some(p => p !== n && p.contains(n)));
  h.classList.add('rv');      // also the "motion is allowed" flag the area scripts read (info.js)
  if (!blocks.length) return;
  blocks.forEach(n => { n.classList.add('rvl'); io.observe(n); });
  // an observer always reports once for every target it watches; if it has not done so, nothing may stay hidden
  setTimeout(() => { if (!heard) h.classList.remove('rv'); }, 2000);
  addEventListener('beforeprint', () => h.classList.remove('rv'));
})();
